import java.util.*;

class Solution {
    public int evalRPN(String[] tokens) {
        Deque<Integer> st = new ArrayDeque<>();
        for (String t : tokens) {
            if (t.length() == 1 && "+-*/".indexOf(t.charAt(0)) >= 0) {
                int b = st.pop(), a = st.pop();   // b is the right operand
                char op = t.charAt(0);
                if (op == '+') st.push(a + b);
                else if (op == '-') st.push(a - b);
                else if (op == '*') st.push(a * b);
                else st.push(a / b);              // Java int division truncates toward zero
            } else {
                st.push(Integer.parseInt(t));     // handles negatives like "-9"
            }
        }
        return st.pop();
    }
}

