function evalRPN(tokens) {
  let i = tokens.length - 1;
  const ev = () => {
    const t = tokens[i--];
    if (!["+", "-", "*", "/"].includes(t)) return Number(t);
    const b = ev(), a = ev();
    return t === "+" ? a + b : t === "-" ? a - b : t === "*" ? a * b : Math.trunc(a / b);
  };
  return ev();
}
